var _REAL_SEG = {};
function _metroNextTrainInfo(mins){
  try {
    var rb = (typeof _buildRouteBrief==='function') ? _buildRouteBrief() : null;
    var seg0 = rb && rb.segments && rb.segments[0];
    if(!seg0) return null;
    var line = seg0.line, stn = seg0.from, nextStn = seg0.to;
    if(!line || !stn) return null;
    var nowMin = (typeof kstMinutesAdj==='function') ? kstMinutesAdj() : (new Date().getHours()*60+new Date().getMinutes());
    var isWk = (typeof _isHolidayOrWeekend==='function') && _isHolidayOrWeekend();

    // ── 진행 방향 판정: 승차역·다음역의 첫차 시각차 (Bug2 _ttSegDir와 동일 원리) ──
    // (2026-10-09: 예전 코드는 한 번도 정의된 적 없는 함수를 불러 항상 '하'가 됐다 →
    //  Bug2 에서 만든 통합 방향 판정 _ttSegDir 를 쓴다)
    var dirKey = '하';
    try{
      if(typeof _ttSegDir==='function' && nextStn){
        var _sd = _ttSegDir(line, [{ stationName: stn }, { stationName: nextStn }], isWk);
        if(_sd === '상행') dirKey = '상'; else if(_sd === '하행') dirKey = '하';
      }
    }catch(e){}

    // ── 시각표 조회: 공식 시각표(_ttOfficialTimes) 우선 ──
    //   _realNextDep는 _REAL_TT(서울 1~9호선)만 담고 있어, 공항철도·인천1·2호선 등은
    //   항상 null → '막차 이후'로 잘못 표시됐다. Bug2에서 만든 통합 조회를 먼저 쓴다.
    var times = null;
    if(typeof _ttOfficialTimes === 'function'){
      try { times = _ttOfficialTimes(line, stn, dirKey, isWk); } catch(e){}
    }

    if(times && times.length){
      var dep = null;
      for(var i=0;i<times.length;i++){ if(times[i] >= nowMin){ dep = times[i]; break; } }
      // 다음 열차가 90분 넘게 남았으면 사실상 운행 종료(심야) → 첫차 안내로 처리
      if(dep != null && (dep - nowMin) > 90){
        return { found:false, depMin:null, arrMin:null, firstMin:((dep%1440)+1440)%1440, line:line, stn:stn, dir:dirKey };
      }
      if(dep != null){
        return { found:true, depMin:dep, arrMin:dep + (mins||0), firstMin:null, line:line, stn:stn, dir:dirKey };
      }
      // 오늘 남은 열차 없음 → 다음 첫차
      var first = null;
      for(var k=0;k<times.length;k++){ if(times[k] >= 240){ first = times[k]; break; } }
      if(first == null) first = times[0];
      return { found:false, depMin:null, arrMin:null, firstMin:((first%1440)+1440)%1440, line:line, stn:stn, dir:dirKey };
    }

    // ── 폴백: 기존 _realNextDep (서울 1~9호선) ──
    var dep2 = (typeof _realNextDep==='function') ? _realNextDep(line, stn, dirKey, nowMin, isWk) : null;
    if(dep2 != null){
      if(dep2 < 1440){
        return { found:true, depMin:dep2, arrMin:dep2 + (mins||0), firstMin:null, line:line, stn:stn, dir:dirKey };
      }
      var fm = dep2 - 1440;
      if(fm == null && typeof _realFirstDep === 'function'){
        var f2 = _realFirstDep(line, stn, dirKey, isWk);
        if(f2 != null) fm = ((f2%1440)+1440)%1440;
      }
      return { found:false, depMin:null, arrMin:null, firstMin:fm, line:line, stn:stn, dir:dirKey };
    }

    // ── 시각표 자체가 없는 노선 → '모름'. '열차 없음'으로 단정하지 않는다 ──
    return { found:null, depMin:null, arrMin:null, firstMin:null, line:line, stn:stn, dir:dirKey };
  } catch(e){ return null; }
}

function _boardDirKey(nd, nextNd){
  var line = (nd && nd.lineName) || '';
  var isHol = (typeof _isHolidayOrWeekend==='function') ? _isHolidayOrWeekend() : false;
  try{
    if(nextNd && typeof _ttSegDir==='function'){
      var d = _ttSegDir(line, [{stationName:nd.name},{stationName:nextNd.name}], isHol);
      if(d) return (d==='상행') ? '상' : '하';
    }
  }catch(e){}
  try{
    if(nextNd && typeof STNDB!=='undefined'){
      var _norm = (typeof _nm==='function') ? _nm : function(x){ return x; };
      var ls = STNDB.filter(function(st){ return st.line===line; });
      var ci = ls.findIndex(function(st){ return _norm(st.name)===_norm(nd.name); });
      var ni = ls.findIndex(function(st){ return _norm(st.name)===_norm(nextNd.name); });
      if(ci>=0 && ni>=0) return (ci<ni) ? '하' : '상';
    }
  }catch(e){}
  return '하';
}

function _boardNextDepTable(nd, nextNd, fromMin){
  if(!nd || fromMin==null) return null;
  var line = nd.lineName || '';
  var dk = _boardDirKey(nd, nextNd);
  var isHol = (typeof _isHolidayOrWeekend==='function') ? _isHolidayOrWeekend() : false;
  var mins = null;
  try{
    if(typeof _ttOfficialTimes==='function'){
      var tms = _ttOfficialTimes(line, nd.name, dk, isHol);
      if(tms && tms.length){
        for(var i=0;i<tms.length;i++){ if(tms[i] >= fromMin){ mins = tms[i]; break; } }
        if(mins==null) mins = tms[0] + 1440;
      }
    }
  }catch(e){}
  if(mins==null && typeof getNextDepartureMins==='function'){
    try{ mins = getNextDepartureMins(line, nd.name, (dk==='상')?'상행':'하행', fromMin); }catch(e){}
  }
  return mins;
}

function _rtArrForward(line, nextName, alightName, bstatnNm){
  try{
    var ord = (typeof _ttOrderOf==='function') ? _ttOrderOf(line) : null;
    if(!ord || !ord.length) return null;
    var nz = (typeof _ttNorm==='function') ? _ttNorm : function(x){ return String(x||'').replace(/역$/,'').trim(); };
    var iN = ord.indexOf(nz(nextName));
    var iA = ord.indexOf(nz(alightName));
    var iB = ord.indexOf(nz(String(bstatnNm||'').replace(/행$/,'')));
    if(iN < 0 || iB < 0) return null;
    if(iA < 0) return null;
    var fwd = (iA > iN);
    return fwd ? (iB > iN) : (iB < iN);   // 종착역이 우리 진행 방향에 있는가
  }catch(e){ return null; }
}
